// _translateHandle: given a handle in the source scope's table, look up
// its rep and mint a fresh handle in the destination scope's table. The
// own/borrow flag propagates — an owned handle stays owned on the other
// side (the caller relinquished ownership), a borrow stays a borrow.
// Returns the destination-scope handle.
//
// P2h.2 correctness gate. Getting own/borrow wrong = use-after-free.
//
// Phase 2ℓ.5 fallback: the sig-typed boundary extractor doesn't yet
// carry accurate `resource_scope_idx` values for handles inside
// wac-plug composed nested boundaries (Handle{resource_scope_idx: 0}
// is a placeholder that only matches when scope 0's table happens
// to hold the referenced resource). Under wac-plug the exporter's
// inline resource table is shared with importers via the type-alias
// linking discipline, so the "correct" behavior when we cannot find
// the handle in the caller-provided scope is to search every
// HANDLE_TABLES entry and return the handle from whichever table
// actually holds it. If the search finds the entry in one table AND
// the destination scope specifies the same table, the returned
// handle is the original (no re-mint needed). If the destination
// specifies a DIFFERENT table, we still copy into it — preserving
// the original translate semantics for genuinely cross-table cases.
function _translateHandle(srcScopeIndex, dstScopeIndex, handle, borrowOverride) {
    let srcTable = HANDLE_TABLES[srcScopeIndex];
    const dstTable = HANDLE_TABLES[dstScopeIndex];
    if (!dstTable) throw new Error("_translateHandle: no destination handle table for scope " + dstScopeIndex);
    let entry = null;
    if (srcTable) {
        const found = srcTable.slots[handle];
        if (found != null && handle !== 0) {
            entry = found;
        }
    }
    if (entry === null) {
        // Fallback: scan all HANDLE_TABLES for a live entry at this
        // handle number. Under wac-plug's shared-table discipline the
        // right table is whichever scope originally created the entry.
        for (let i = 0; i < HANDLE_TABLES.length; i++) {
            const t = HANDLE_TABLES[i];
            if (!t) continue;
            const slot = t.slots[handle];
            if (slot != null && handle !== 0) {
                entry = slot;
                srcTable = t;
                break;
            }
        }
    }
    if (entry === null) {
        throw new Error("resource handle " + handle + " not present in scope " + srcScopeIndex + " (freed or out-of-range)");
    }
    // The borrowOverride parameter lets the WIT-declared borrow/own
    // discipline dictate the resulting flag regardless of the src
    // entry's flag — a borrow<T> arg is always borrowed on both sides
    // even if the caller happened to own the source-scope handle.
    const owned = (typeof borrowOverride === "boolean") ? !borrowOverride : !!entry.owned;
    // Same table on both sides: the handle already refers to the
    // desired entry — no re-mint needed. This preserves handle
    // identity across the wac-plug boundary and avoids leaking
    // per-call handle-table entries in shared-table setups.
    if (srcTable === dstTable) {
        return handle;
    }
    return _rscTableCreate(dstTable, entry.rep, owned);
}

// Option E Phase 2ℓ.12 — rep-as-handle importer method dispatch (V7).
//
// wit-bindgen 0.36+ emits exporter core modules that use *rep-as-handle*
// for their exported resources: the module imports `[resource-new]X` and
// `[resource-drop]X` from the component runtime but does NOT import
// `[resource-rep]X` — the compiler dead-code-eliminated the lookup because
// its method implementations dereference the incoming handle *directly* as
// the `*mut _XRep<T>` pointer (see wit-bindgen-rust v0.36.0
// `src/interface.rs:207-248`). Under this convention the "handle" that
// crosses the wasm ABI boundary IS the rep pointer.
//
// wit-js-bindgen's own runtime wires `[resource-new]X = (rep) =>
// _rscTableCreateOwn(tbl, rep)` — that returns a JS-side slot index (a
// small integer). The exporter (built with wit-bindgen 0.36+) then treats
// that slot index as a pointer, reads unmapped low memory, and observes
// zero-fill — the on-shelf reason its methods silently returned "Closed"
// / "Stdin"-shaped garbage in Phase 2ℓ.11.
//
// `_lookupRep(handle)` reverses the slot-allocation step: given a JS-side
// slot index, it finds the resource-table entry that owns it and returns
// the raw rep pointer. The cross-scope method trampoline emitter uses this
// at boundaries that target a rep-as-handle exporter, replacing the
// `_translateHandle(...)` call it would otherwise emit — because the
// exporter never asked for a re-minted destination-scope handle; it needs
// the rep.
//
// The scan matches _translateHandle's fallback scan discipline: under
// wac-plug's shared-table linking the caller may not know which specific
// HANDLE_TABLES entry the handle lives in. Scanning is O(#scopes) which
// is small (adopt-lane composed components have <10 tables). A miss
// throws — silent-corruption discipline; a rep pointer of 0 would let the
// exporter dereference null.
function _lookupRep(handle) {
    if (handle === 0) throw new Error("_lookupRep: resource handle 0 is reserved");
    for (let i = 0; i < HANDLE_TABLES.length; i++) {
        const t = HANDLE_TABLES[i];
        if (!t) continue;
        const e = t.slots[handle];
        if (e != null) return e.rep;
    }
    throw new Error("_lookupRep: resource handle " + handle + " not found in any live table");
}


// Suspension backend registry. Populated at module load. Backend
// selection happens at every `_suspend` / `_invoke` call via
// `_selectSuspensionBackend`; the registry itself is module-scope
// and the JSPI backend is instance-agnostic in PR 1.
const _SUSPENSION_BACKENDS = { jspi: null, asyncify: null };

// JSPI backend. Instance-agnostic (`WebAssembly.Suspending` doesn't need
// an instance handle; `WebAssembly.promising` binds one export at a time).
if (typeof WebAssembly !== "undefined"
    && typeof WebAssembly.Suspending === "function"
    && typeof WebAssembly.promising === "function") {
    _SUSPENSION_BACKENDS.jspi = {
        isAvailable: (_instance) => true,
        bindInstance: (_instance) => ({
            suspend: (asyncFn) => new WebAssembly.Suspending(asyncFn),
            invoke: (exportFn) => {
                if (typeof exportFn !== "function") return exportFn;
                // A JS-authored function has an own `.prototype`
                // property; raw wasm exports do not. Pass JS closures
                // through unchanged (the caller can already `await`
                // their Promise). Everything else goes through
                // `WebAssembly.promising` — with a try/catch fallback
                // in case the engine rejects the wrap for shape
                // reasons we did not anticipate.
                if (Object.prototype.hasOwnProperty.call(exportFn, "prototype")) {
                    return exportFn;
                }
                try {
                    return WebAssembly.promising(exportFn);
                } catch {
                    return exportFn;
                }
            },
        }),
    };
}

// Per-instance backend selection. JSPI first, Asyncify second, "none"
// last. Do not alphabetise — the source order is load-bearing.
function _selectSuspensionBackend(instance) {
    if (_SUSPENSION_BACKENDS.jspi
        && _SUSPENSION_BACKENDS.jspi.isAvailable(instance)) return "jspi";
    if (_SUSPENSION_BACKENDS.asyncify
        && _SUSPENSION_BACKENDS.asyncify.isAvailable(instance)) return "asyncify";
    return "none";
}

// Top-level primitives every `_suspend(...)` / `_invoke(...)` emit
// site dispatches through. The `"none"` backend does NOT silently
// pass an async import through to wasm — a returned Promise would be
// lowered as garbage and the wasm caller would see corruption. Match
// the "lazy per-call error at suspend time" contract: the module
// loads fine on non-JSPI hosts, but the first actual suspending call
// throws a message pointing at JSPI / --async-fallback=asyncify.
function _suspend(asyncFn) {
    const backend = _selectSuspensionBackend(null);
    if (backend === "none") {
        return function witBindgenSuspendUnsupported() {
            throw new Error(
                "wit-js-bindgen: this build declared suspending imports, "
                + "but the host has no JSPI (WebAssembly.Suspending / "
                + "promising) and no Asyncify fallback was bundled. "
                + "Either use a JSPI-capable host (Chrome, Node >= 22), "
                + "or regenerate with --async-fallback=asyncify."
            );
        };
    }
    return _SUSPENSION_BACKENDS[backend].bindInstance(null).suspend(asyncFn);
}

// `_invoke` wraps a wasm export the caller wants to `await`. On JSPI
// hosts, `_SUSPENSION_BACKENDS.jspi.invoke(...)` routes through
// `WebAssembly.promising` (returns a callable that returns a Promise
// when invoked); on non-JSPI hosts it returns the export unchanged (a
// sync export that never suspends works fine, and any suspending
// import it transitively reaches would throw via `_suspend`'s
// lazy-error path above). The Asyncify backend's `invoke(exportFn,
// args)` is async and returns a Promise directly, taking `args` as its
// SECOND parameter — chaining `_invoke(fn)(args)` off a naked
// `bindInstance(null).invoke(fn)` return would call `(args)` on that
// Promise. Wrap the Asyncify branch in a callable that forwards
// `arguments` as the SECOND parameter, mirroring the per-instance
// driver façade shape in `emit_instantiate` (see
// `src/emit/js.rs::emit_instantiate` PR3.5a Fix B).
function _invoke(exportFn) {
    const backend = _selectSuspensionBackend(null);
    if (backend === "none") return exportFn;
    if (backend === "jspi") return _SUSPENSION_BACKENDS.jspi.bindInstance(null).invoke(exportFn);
    return function () { return _SUSPENSION_BACKENDS[backend].bindInstance(null).invoke(exportFn, arguments); };
}

// wit-js-bindgen: --async-imports supplied — imports below are wrapped in `_suspend(...)`.
// The runtime picks a suspension backend at call time via `_selectSuspensionBackend`:
// JSPI when the host provides `WebAssembly.Suspending` + `.promising`; the injected
// Asyncify driver when present (Phase B PR 3+); otherwise a lazy-error backend that
// throws only when a suspending call is actually invoked. See docs/design-async-phase-b.md.

export const SuspensionBackends = Object.freeze({ jspi: _SUSPENSION_BACKENDS.jspi, asyncify: _SUSPENSION_BACKENDS.asyncify });

